head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.clickId;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF37075.xml";
scwin.real_invstg_impr_seq;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var com_cd = txb_isur_cd.getValue();
    url = "/RealInvstgImpr.do?method=listRealInvstgImpr&COM_CODE=" + com_cd + "&FROM_DATE=" + edt_SDate.getValue() + "&TO_DATE=" + edt_EDate.getValue() + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_RealInvstgImprList.DataID = encodeURI(url);
    dts_RealInvstgImprList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_getReal_invstg_impr_seq = function() {
    return scwin.real_invstg_impr_seq;
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_Input_onclick = async function() {
    scwin.clickId = "input";
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF37076.gfm", "개선계획의 주요내용 입력", 200, 100, 666, 305, "window");
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_RealInvstgImprList_OnFail = function() {
    $c.stf.alert_error(dts_RealInvstgImprList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_RealInvstgImprList_OnLoadError = function() {
    $c.stf.alert_error(dts_RealInvstgImprList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_RealInvstgImprList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_RealInvstgImprList.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gIsurCd = dts_RealInvstgImprList.getCellData(row, "ISUR_CD");
    scwin.real_invstg_impr_seq = dts_RealInvstgImprList.getCellData(row, "REAL_INVSTG_IMPR_SEQ");
    if (colid == "DETAILCON") {
        scwin.clickId = scwin.real_invstg_impr_seq;
        await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF37076.gfm", "개선계획의 주요내용 조회", 200, 100, 666, 305, "window");
    } else if (colid == "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "실질심사 개선계획서", "", "2");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    edt_EDate.setValue(vCurDate);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market == '9') {
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
    } else if (js_market == '1' || js_market == '2') {
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
        rdo_MKT_ID.setDisabled(true);
    }
    //유가, 로그인 부서코드가 2500(상장부)이거나 상위부서코드가 2500일때만 입력버튼 활성화
    if (js_market == '1') {
        if (js_dep_cd == '2500' || js_belngdepcd == '2500') {
            $c.stf.showObj(btn_Input, true);
        } else {
            $c.stf.showObj(btn_Input, false);
        }
    }
    //코스닥, 로그인 부서코드가 3H00(상장관리부)이거나 상위부서코드가 3H00일때만 입력버튼 활성화
    else if (js_market == '2') {
        if (js_dep_cd == '3H00' || js_belngdepcd == '3H00') {
            $c.stf.showObj(btn_Input, true);
        } else {
            $c.stf.showObj(btn_Input, false);
        }
    }
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
